import { expect, test } from "vitest";
import { renderCodeowners } from "./files.ts";

test("maintainers own everything and the owners team owns the governance files", () => {
  expect(renderCodeowners(["alice", "natrontech/developers"])).toBe(
    [
      "# Generated by natrontech/oss-governance, change the maintainers there",
      "*                    @alice @natrontech/developers",
      "",
      "/.github/CODEOWNERS  @natrontech/open-source-owners",
      "/SECURITY.md         @natrontech/open-source-owners",
      "/LICENSE             @natrontech/open-source-owners",
      "",
    ].join("\n"),
  );
});
